import{z as l,x as i,o as r,c as A,q as n,j as t,D as o,d as e,s as d,S as s,b as a}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"舍入模式","description":"","frontmatter":{"title":"舍入模式","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/rounding-modes.md","filePath":"cs/rounding-modes.md","lastUpdated":1791413859000}'),p={name:"cs/rounding-modes.md"};function u(D,E,c,m,C,h){const B=i("Mermaid");return r(),A("div",null,[E[2]||(E[2]=n('<h1 id="舍入模式" tabindex="-1">舍入模式 <a class="header-anchor" href="#舍入模式" aria-label="Permalink to &quot;舍入模式&quot;">​</a></h1><div class="epigraph"><p>精确结果常常不在格子上；往哪一个可表示的邻居靠，必须先约定，否则同一算法换一台机器会换一批比特。</p><footer>—— 据 IEEE Std 754-2008；Knuth, The Art of Computer Programming, Vol. 2；Goldberg, 1991 整理</footer></div><p>上一课<a href="/cs/ieee-754">IEEE 754</a>钉死了 <code>binary32</code>/<code>binary64</code> 的位型，并点名默认 round-to-nearest-even。本课不重列偏置与隐藏位，也不从「实数逼近论」另起。缺口是：有限尾数上，加减乘除的<strong>精确数学结果</strong>往往落在两个可表示数之间。默认模式被点了名，还没有说清还有哪些模式、平局怎么破、有向舍入给谁用。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>754 的格子不是 \\(\\mathbb{R}\\)。运算先产生理想结果，再映射回格子。缺口因此不是再切指数宽度，而是钉一套<strong>舍入属性</strong>：最近偶数、朝零、朝正无穷、朝负无穷，以及 2008 年写清的 ties-to-away。同一表达式、同一操作数，模式不同则结果比特可以不同；数值库与区间算术依赖「朝哪边」可重复。</p><p>本课只钉二进制格式上这几条。非规格化与 NaN 在精确结果落到零附近或无效时才成为主角，那是<a href="/cs/denormal-nan">下一课</a>。</p><h3 id="最近偶数不是「四舍五入」" tabindex="-1">最近偶数不是「四舍五入」 <a class="header-anchor" href="#最近偶数不是「四舍五入」" aria-label="Permalink to &quot;最近偶数不是「四舍五入」&quot;">​</a></h3><p>十进制四舍五入在 <code>.5</code> 处总是远离零，会引入单向偏差。754 的默认是：距离相等时选最低有效位为 \\(0\\) 的那个（偶数）。把学校里的四舍五入直接当成默认，统计上的均值会偏，也与硬件默认不符。</p><p><span class="marginnote">数字实例：把 2.5 与 3.5 各舍入到整数——学校的四舍五入分别给 3 和 4；ties-to-even 则分别给 2 和 4。两者在 2.5 处分道扬镳：半数的平局被压向偶数尾数，长程求和才不会单向漂移。</span></p><p><span class="marginnote">IEEE 754-2008 §4 把舍入属性写成独立于格式的条款。Knuth Vol. 2 §4.2 强调浮点算术是有限集上的运算，舍入是定义的一部分，不是事后修饰。Goldberg 用例子说明同一表达式换模式后差在哪一位。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>记理想结果为 \\(x\\)，可表示集为 \\(F\\)。最近：选 \\(F\\) 中距 \\(x\\) 最小者；平局时默认选偶数尾数（<code>roundTiesToEven</code>），或选幅值更大者（<code>roundTiesToAway</code>）。有向：<code>roundTowardZero</code> 取不比 \\(x\\) 更远离零的那个；<code>roundTowardPositive</code> / <code>roundTowardNegative</code> 分别不小于 / 不大于 \\(x\\)。不精确时置 inexact 旗标——旗标如何进陷阱，本课不接。</p>',12)),(r(),t(s,null,{default:o(()=>[d(B,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20IDEAL%5B%22%E7%90%86%E6%83%B3%E5%AE%9E%E7%BB%93%E6%9E%9C%22%5D%20--%3E%20MODE%5B%22%E7%BA%A6%E5%AE%9A%E8%88%8D%E5%85%A5%E5%B1%9E%E6%80%A7%22%5D%0A%20%20MODE%20--%3E%20GRID%5B%22%E6%A0%BC%E5%AD%90%E4%B8%8A%E7%9A%84%E9%82%BB%E5%B1%85%22%5D%0A%20%20GRID%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E9%9B%B6%E9%99%84%E8%BF%91%E4%B8%8E%20NaN%22%5D%0A"})]),fallback:o(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("p",null,"默认模式对大多数科学计算够用。区间算术需要有向舍入夹住真值；本课只承认这件事，不构造区间库。",-1)),E[4]||(E[4]=a("p",null,[a("span",{class:"marginnote"},"为什么重要：区间算术的合同是「真值一定落在区间内」。下界必须朝负无穷舍、上界朝正无穷舍，两个端点才各自向外偏；若都按默认最近舍入，真值可能落在区间外，「包含」的保证当场作废。")],-1)),E[5]||(E[5]=a("h2",{id:"机制",tabindex:"-1"},[e("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[6]||(E[6]=a("p",null,[e("FMA 把乘加熔成一次舍入，与「先乘后加」两次舍入可以不同——上一课已承认。本课补的是：即便单次运算，模式也是 ABI 与控制寄存器的一部分。RISC-V 的 "),a("code",null,"frm"),e(" 选择模式；语言默认通常绑最近偶数。比较与哈希仍先问比的是比特还是数值：舍入改变的是产生哪些比特。")],-1)),E[7]||(E[7]=a("p",null,"理想结果落在两格之间时，各模式各自选哪一格：",-1)),(r(),t(s,null,{default:o(()=>[d(B,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E7%90%86%E6%83%B3%E7%BB%93%E6%9E%9C%20x%20%E8%90%BD%E5%9C%A8%E7%9B%B8%E9%82%BB%E4%B8%A4%E6%A0%BC%20a%20%E4%B8%8E%20b%20%E4%B9%8B%E9%97%B4%22%5D%20--%3E%20NE%7B%22%E5%88%B0%20a%20%E4%B8%8E%20b%20%E7%9A%84%E8%B7%9D%E7%A6%BB%E7%9B%B8%E7%AD%89%EF%BC%9F%22%7D%0A%20%20NE%20--%3E%7C%22%E4%B8%8D%E7%AD%89%22%7C%20RN%5B%22%E6%9C%80%E8%BF%91%E5%81%B6%E6%95%B0%EF%BC%9A%E9%80%89%E6%9B%B4%E8%BF%91%E7%9A%84%E4%B8%80%E6%A0%BC%22%5D%0A%20%20NE%20--%3E%7C%22%E7%9B%B8%E7%AD%89%22%7C%20TIE%5B%22%E5%B9%B3%E5%B1%80%EF%BC%9A%E9%80%89%E5%B0%BE%E6%95%B0%E6%9C%80%E4%BD%8E%E4%BD%8D%E4%B8%BA%200%20%E7%9A%84%E4%B8%80%E6%A0%BC%22%5D%0A%20%20X%20--%3E%20TZ%5B%22%E6%9C%9D%E9%9B%B6%EF%BC%9A%E5%8F%96%E6%9B%B4%E9%9D%A0%E8%BF%91%E9%9B%B6%E7%9A%84%E4%B8%80%E6%A0%BC%22%5D%0A%20%20X%20--%3E%20PU%5B%22%E6%9C%9D%E6%AD%A3%E6%97%A0%E7%A9%B7%EF%BC%9A%E5%8F%96%E4%B8%8D%E5%B0%8F%E4%BA%8E%20x%20%E7%9A%84%E4%B8%80%E6%A0%BC%22%5D%0A%20%20X%20--%3E%20PD%5B%22%E6%9C%9D%E8%B4%9F%E6%97%A0%E7%A9%B7%EF%BC%9A%E5%8F%96%E4%B8%8D%E5%A4%A7%E4%BA%8E%20x%20%E7%9A%84%E4%B8%80%E6%A0%BC%22%5D%0A%20%20RN%20--%3E%20FLAG%5B%22%E7%BB%93%E6%9E%9C%E4%B8%8D%E7%B2%BE%E7%A1%AE%E5%88%99%E7%BD%AE%20inexact%20%E6%97%97%E6%A0%87%22%5D%0A%20%20TIE%20--%3E%20FLAG%0A%20%20TZ%20--%3E%20FLAG%0A%20%20PU%20--%3E%20FLAG%0A%20%20PD%20--%3E%20FLAG%0A"})]),fallback:o(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[8]||(E[8]=n('<p><span class="marginnote">常见误区：初学者容易把舍入当成「损失一点精度」的无害收尾。实际上舍入模式是写进控制寄存器的全局状态——中途悄悄改它，同一个函数在同一台机器上都会换一批输出比特，回归测试也就跟着全红。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把十进制 754 的舍入另开一张表，不讨论随机舍入（stochastic rounding）作为训练技巧——那不是 754-2008 的强制属性。也不把误差界写成定理：Goldberg 的 ulp 讨论到能用为止，完整舍入误差分析不进主干。</p><p>后课默认：未声明时，二进制浮点舍入是 round-to-nearest-even；改变模式会改变结果比特。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>舍入把理想结果映回 754 格子；模式必须先约定。</li><li>默认最近偶数，平局选偶数尾数，不是十进制四舍五入。</li><li>有向舍入服务区间与定向误差；零附近的特殊值下一课再钉。</li><li>出处：IEEE 754-2008；Knuth, TAOCP Vol. 2；Goldberg, 1991。</li></ul>',6))])}const f=l(p,[["render",u]]);export{b as __pageData,f as default};
